@page "/chat"
@using sv_281fd91f9d4d4ea480ed5fbb0cb88b42.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    SelectedChannelId="_selectedChannel?.Id"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(_threadOpen ? "thread-open" : "")">
        @if (_selectedChannel is not null)
        {
            <MessagePanel ChannelName="@_selectedChannel.Name"
                          ChannelDescription="@_selectedChannel.Description"
                          Messages="_messages"
                          ThreadReplyCounts="_threadReplyCounts"
                          OnLoadMore="LoadOlderMessages"
                          OnOpenThread="OpenThread"
                          OnReact="AddReaction"
                          OnSendMessage="SendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
