+        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
+        _threadReplies.Add(reply);
+
+        // Update reply count
+        _threadReplyCounts[_threadRootMessage.Id] =
+            _threadReplyCounts.GetValueOrDefault(_threadRootMessage.Id) + 1;
+    }
+
+    private async Task AddReaction((int MessageId, string Emoji) reaction)
+    {
+        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
+        // Refresh messages to show updated reactions
+        if (_selectedChannel is not null)
+        {
+            _messages = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _messages.Count);
+        }
+    }
+
+    private async Task<Dictionary<int, int>> BuildThreadReplyCounts()
+    {
+        var counts = new Dictionary<int, int>();
+        // Count messages that are replies (have ReplyToId) and group by root
+        foreach (var msg in _messages.Where(m => m.ReplyToId.HasValue))
+        {
+            var rootId = msg.ReplyToId!.Value;
+            counts[rootId] = counts.GetValueOrDefault(rootId) + 1;
+        }
+        return counts;
+    }
